/**
 * The contract between the aircraft GLB and the code that animates it.
 *
 * The model is generated by scripts/build-aircraft.mjs. Any replacement model
 * works as long as it keeps these node and material names, the same axes
 * (+Z nose, +Y up, +X left wing) and its origin on the ground under the main
 * landing gear.
 */

export const AIRCRAFT_MODEL_URL = "/models/sr-01.glb";

/** Height of the fuselage centreline above the origin (the roll axis). */
export const AIRCRAFT_CENTRELINE_Y = 1.95;

/** Overall dimensions in metres, used for camera framing. */
export const AIRCRAFT_DIMENSIONS = {
  length: 21,
  wingspan: 20.9,
  height: 6.5,
} as const;

export const AIRCRAFT_NODES = {
  root: "SR01",
  fanLeft: "Fan_L",
  fanRight: "Fan_R",
  gearNose: "Gear_Nose",
  gearMainLeft: "Gear_Main_L",
  gearMainRight: "Gear_Main_R",
  lightsNav: "Lights_Nav",
  lightsBeacon: "Lights_Beacon",
  lightsLanding: "Lights_Landing",
  decalLeft: "Decal_SR01_L",
  decalRight: "Decal_SR01_R",
} as const;

/** Empty nodes that mark where light glows are drawn. */
export const AIRCRAFT_LIGHT_ANCHORS = {
  navLeft: "Light_Nav_L",
  navRight: "Light_Nav_R",
  tail: "Light_Tail",
  beaconTop: "Light_Beacon_Top",
  beaconBottom: "Light_Beacon_Bottom",
  landingLeft: "Light_Landing_L",
  landingRight: "Light_Landing_R",
} as const;

export const AIRCRAFT_MATERIALS = {
  pearl: "Paint_Pearl",
  graphite: "Paint_Graphite",
  glass: "Glass_Dark",
  polished: "Metal_Polished",
  darkMetal: "Metal_Dark",
  fan: "Metal_Fan",
} as const;

const DEG = Math.PI / 180;

/**
 * Landing gear retraction, as rotations about each gear's hinge.
 * `extension` is 1 with the gear down and 0 fully retracted.
 */
export const GEAR_TRAVEL = {
  /** Nose gear swings forward and up, about the X axis. */
  noseAngle: -118 * DEG,
  /** Main gear swings inward into the belly fairing, about the Z axis. */
  mainAngle: 86 * DEG,
  /** Below this extension the gear is fully stowed and can be hidden. */
  stowedBelow: 0.02,
} as const;

export interface GearPose {
  noseRotationX: number;
  mainLeftRotationZ: number;
  mainRightRotationZ: number;
  visible: boolean;
}

/** Eases gear travel so it starts and stops gently. */
function easeInOut(t: number): number {
  return t * t * (3 - 2 * t);
}

export function gearPose(extension: number): GearPose {
  const e = Math.min(1, Math.max(0, extension));
  const retracted = easeInOut(1 - e);
  return {
    noseRotationX: GEAR_TRAVEL.noseAngle * retracted,
    // The left gear is on +X, so swinging inward is a negative rotation.
    mainLeftRotationZ: -GEAR_TRAVEL.mainAngle * retracted,
    mainRightRotationZ: GEAR_TRAVEL.mainAngle * retracted,
    visible: e > GEAR_TRAVEL.stowedBelow,
  };
}

/**
 * Live aircraft state that is not part of its transform. Mutated in place by
 * the flight controller and read by the Aircraft component each frame.
 */
export interface AircraftState {
  /** 1 = gear down, 0 = retracted. */
  gear: number;
  /** 0 = idle, 1 = takeoff thrust. Drives fan speed. */
  throttle: number;
  /** 0 = landing lights off, 1 = on. */
  landingLights: number;
  /** How strongly light glows read against the scene: 1 at night, low in daylight. */
  glow: number;
}

export function createAircraftState(): AircraftState {
  return { gear: 1, throttle: 0.15, landingLights: 1, glow: 1 };
}
